import { create } from 'zustand'

export type ViewType = 'home' | 'subjects' | 'chapters' | 'quiz' | 'result' | 'scoreboard' | 'progress' | 'dailyChallenge' | 'badges' | 'leaderboard' | 'teacherDashboard' | 'profile' | 'lessons' | 'practice' | 'studyCalendar' | 'parentCorner' | 'documents'

export interface StudentInfo {
  name: string
  className: string
  schoolName: string
}

export interface QuizResult {
  score: number
  totalPoints: number
  answers: Record<string, string>
  quizId: string
  timeTaken: number
}

interface AppStore {
  currentView: ViewType
  selectedGrade: number | null
  selectedSubject: string | null
  selectedQuizId: string | null
  studentInfo: StudentInfo | null
  quizResult: QuizResult | null
  previousView: ViewType | null

  // Actions
  setView: (view: ViewType) => void
  selectGrade: (grade: number) => void
  selectSubject: (subject: string) => void
  startQuiz: (quizId: string, studentInfo: StudentInfo) => void
  setQuizResult: (result: QuizResult) => void
  goBack: () => void
  goHome: () => void
  clearStudent: () => void
}

const viewHistory: ViewType[] = []

export const useAppStore = create<AppStore>((set, get) => ({
  currentView: 'home',
  selectedGrade: null,
  selectedSubject: null,
  selectedQuizId: null,
  studentInfo: null,
  quizResult: null,
  previousView: null,

  setView: (view: ViewType) => {
    const currentView = get().currentView
    viewHistory.push(currentView)
    set({ currentView: view, previousView: currentView })
  },

  selectGrade: (grade: number) => {
    const currentView = get().currentView
    viewHistory.push(currentView)
    set({ selectedGrade: grade, currentView: 'subjects', previousView: currentView })
  },

  selectSubject: (subject: string) => {
    const currentView = get().currentView
    viewHistory.push(currentView)
    set({ selectedSubject: subject, currentView: 'chapters', previousView: currentView })
  },

  startQuiz: (quizId: string, studentInfo: StudentInfo) => {
    const currentView = get().currentView
    viewHistory.push(currentView)
    set({
      selectedQuizId: quizId,
      studentInfo,
      currentView: 'quiz',
      previousView: currentView,
      quizResult: null,
    })
  },

  setQuizResult: (result: QuizResult) => {
    const currentView = get().currentView
    viewHistory.push(currentView)
    set({
      quizResult: result,
      currentView: 'result',
      previousView: currentView,
    })
  },

  goBack: () => {
    const prevView = viewHistory.pop() || 'home'
    set({ currentView: prevView })
  },

  goHome: () => {
    viewHistory.length = 0
    set({
      currentView: 'home',
      selectedGrade: null,
      selectedSubject: null,
      selectedQuizId: null,
      // Keep studentInfo - DON'T clear it
      quizResult: null,
      previousView: null,
    })
  },

  clearStudent: () => {
    set({ studentInfo: null })
    if (typeof window !== 'undefined') {
      localStorage.removeItem('cogiaohaianh-student')
    }
  },
}))

// Persist studentInfo to localStorage
useAppStore.subscribe(
  (state) => state.studentInfo,
  (studentInfo) => {
    if (typeof window !== 'undefined') {
      if (studentInfo) {
        localStorage.setItem('cogiaohaianh-student', JSON.stringify(studentInfo))
      }
    }
  }
)

// Hydrate studentInfo from localStorage on load
const savedStudent = typeof window !== 'undefined'
  ? JSON.parse(localStorage.getItem('cogiaohaianh-student') || 'null') as StudentInfo | null
  : null
if (savedStudent) {
  useAppStore.setState({ studentInfo: savedStudent })
}
